pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: strongly prefer tight fits (low post_residual).
    // Late stream: relax slightly, tolerate larger residuals to keep bins open.
    let poly = norm_post * norm_post * (1.0 - progress) * 3.0
        + norm_post * progress * 0.5
        + norm_post.powi(3) * (0.5 + progress);

    // Smooth interaction: dead space penalty grows with item size fraction.
    let size_frac = item_size as f64 / cap;
    let dead = (norm_post * (1.0 - size_frac)).powi(2) * 2.0;

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins.
    let fit_term = if fitting_bins_count <= 1 { -1.5 } else { 0.0 };

    // Lookahead: gently reward leaving room for the next item.
    let next_bonus = if next_item_size > 0 {
        -0.5 * (next_item_size as f64 / cap) * (1.0 - (norm_post - next_item_size as f64 / cap).abs())
    } else {
        0.0
    };

    // Slight penalty for opening new bins when many are open.
    let open_penalty = (open_bins_count as f64).ln() * 0.05 * norm_post;

    let mut score = post + poly * cap * 0.1 + dead * cap * 0.1 + fit_term + next_bonus + open_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual: dead space is only "reusable"
    // if a future item of a standard size class can land in it.
    // Class bins into residue bands: tiny (0..=5), small (6..=15),
    // medium (16..=30), large (31..=60), huge (61..=99).
    let band = match post_residual {
        0 => 0.0,
        1..=5 => 1.0,
        6..=15 => 2.0,
        16..=30 => 3.0,
        31..=60 => 4.0,
        _ => 5.0,
    };

    // Reward creating a residual band that matches the lookahead item:
    // if next_item_size fits exactly into post_residual, this placement
    // chains two items efficiently.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0; // exact two-item chain
        } else if next_item_size <= post_residual {
            // Partially reusable: reward proportional to how tight the fit is.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * tightness;
        } else {
            // Lookahead cannot use this bin: penalize small dead bands more
            // (they are hard to fill later), large bands are more flexible.
            score += band * 12.0;
        }
    }

    // Integer-division harmonic structure: residual / 10 gives a coarse
    // "slot count". Reward keeping slot counts aligned with typical item
    // granularity (items 1..100, often multiples of 5 or 10).
    let slots = post_residual / 10;
    score -= slots as f64 * 3.0;

    // Penalize wasting a nearly-full bin on a tiny item when other bins fit.
    if item_size <= 20 && post_residual >= 40 && fitting_bins_count > 1 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    // Base penalty grows with number of open bins (bin proliferation).
    if bin_residual == bin_capacity {
        score += 120.0 + 15.0 * open_bins_count as f64;
        // If the lookahead item is huge, a fresh bin is actually valuable
        // since it preserves full flexibility.
        if next_item_size > 60 {
            score -= 90.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference for bins whose residual is below the mean residual
    // (fill down the fuller bins first, keep empty-ish bins flexible).
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Tie-break: slight noise-free determinism via step parity on exact ties
    // is unnecessary; instead prefer earlier-created (smaller residual) bins
    // implicitly handled above.

    score
}

