        if post_residual >= next_item_size {
            // Perfect chaining: next item fits exactly or leaves small waste
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - chain_waste * 2.0;
            if post_residual == next_item_size {
                score -= 300.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving residual well below average means this bin is being "closed out"
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 80.0 * (0.5 - rel); // consolidating small residuals is good
        } else if rel > 1.5 {
            score += 40.0 * (rel - 1.5); // leaving oversized residual is wasteful
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

