        let base_penalty = 120.0;
        // Large items with no lookahead use: opening fresh is reasonable
        let size_bonus = if item_size >= 50 { 60.0 } else { 0.0 };
        // If next item is small, a fresh bin can chain it: soften penalty
        let chain_soften = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            40.0
        } else {
            0.0
        };
        score += base_penalty - size_bonus - chain_soften;
        // Late in the stream, avoid opening new bins even more
