}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasted potential
            score += 2.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable late in the stream or when open bins are poor fits.
        let fit_pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 - 10.0 * progress + fit_pressure;
        // If mean residual across open bins is high, prefer reusing them.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
    } else {
        // Favor reusing bins with lower residuals (consolidation).
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Mild reward for keeping the number of open bins low.
        score -= 0.05 * open_bins_count as f64;
    }

    // Time-horizon coupling: early stream, be conservative about waste; late stream, pack greedily.
    let horizon = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    score *= 1.0 + 0.1 * (1.0 - horizon);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = poly * cap;

    // Reward tight fits smoothly via cubic decay of post_residual
    score -= 3.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual too small for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 0.5 * gap / cap;
        } else {
            score += 0.8 * (-gap) / cap;
        }
    }

    // Penalize scattering residual relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: mildly discourage opening a new bin early, allow later
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 10 deciles.
    let cap_frac = (post_residual * 10) / bin_capacity; // 0..=10
    let harmonic_bonus: f64 = match cap_frac {
        0 => -30.0, // near-perfect fill
        1 => -12.0,
