        score -= 1.0;
    }

    // Lookahead coupling: does post_residual fit the next item well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_frac = (next_item_size * 10) / bin_capacity;
            // Reward when next item fits snugly (post_residual - next small)
            let gap = post_residual - next_item_size;
            if gap <= bin_capacity / 10 {
                score -= 10.0;
            } else if gap <= bin_capacity / 4 {
                score -= 4.0;
            }
            // If next item is large, prefer bins whose leftover class matches
            if next_frac >= 5 && cap_frac >= 5 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this leftover: penalize leaving medium dead space
            if cap_frac >= 2 && cap_frac <= 4 {
                score += 6.0;
            }
        }
    } else {
        // Last item: just fill as much as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 25.0;
        // If many bins already fit the item elsewhere, discourage new bin.
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // Early in stream, new bins are cheap; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across open bins is small, opening a new bin is fine.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 18.0;
        }
    }

    // Slight preference for tighter bins when competition exists.
    if fitting_bins_count > 2 {
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; residuals below the next item's size are semi-dead.
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 50.0;
    } else {
        // Small unusable gap (< min item size) is dead space: heavy penalty.
        if post_residual < 1 {
            score += 40.0;
        }
        // Semi-dead space: gap smaller than the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Waste fraction weighting: penalize proportion of wasted capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Tight fit reward: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins would create dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; slightly worse than a decent fit.
        score = 60.0 + 0.1 * open_bins_count as f64;
        // Late in the stream, prefer reusing bins more aggressively.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If a perfect or near-perfect fit exists elsewhere, new bin is unattractive.
        if post_residual == 0 || fill_ratio > 0.9 {
            score += 30.0;
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins with residuals close to the item (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when
    // no existing bin offers a good (near-exact) fit.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is cheap early in the stream, expensive late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
        // If many bins fit, prefer reusing one; new bin less attractive.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Small items waste a fresh bin less than big items... actually big
        // items in a fresh bin are fine; penalize only when a big next item
        // would be stranded. Keep modest.
        return score;
    }

    // Core lookahead: perfect 2-step match => huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact chain fill
        } else if post_residual > next_item_size {
            // next item still fits: reward tighter leftover chain gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to
            // how much of the next item is stranded
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.6 * stranded;
        }
    } else {
        // Last item: pure tightest fit, no future to preserve.
        score -= 5.0;
    }

    // Penalize unusable slivers (dead space below the minimum item size).
    if post_residual < 1 {
        score -= 30.0; // perfectly packed bin, celebrate
    } else if post_residual <= 10 {
        score += 0.5 * (11.0 - post_residual as f64); // small sliver penalty
    }

    // Relative-to-mean coupling: bins below mean residual are "tighter"
    // than average; favoring them preserves loose bins for large items.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to close out bins when many are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that no plausible future item (>=10... >=1) can use.
    if post_residual > 0 {
        // residual smaller than the smallest conceivable item is pure waste
        if post_residual < 5 {
            score += 30.0;
        } else if post_residual < item_size {
            score += 4.0 * (1.0 - (post_residual as f64) / (item_size as f64));
        }
    }

    // Lookahead: if next item fits in post_residual, reward; if it just misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // placing here would block the next item which could have fit now
            score += 6.0;
        }
        // exact pairing bonus
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: empty full-residual bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when open bins are mostly full /
        // when no open bin fits well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        // cost of a new bin grows with number of open bins and stream progress
        score += 55.0 + 0.8 * open_bins_count as f64 + 40.0 * progress;
        // but discount if existing bins are crowded (avg fill high) -> spreading is good
        score -= 35.0 * avg_fill;
        // if item is large, a fresh bin is more attractive
        score -= 0.15 * item_size as f64;
    }

    // Mild penalty for placing into bins whose residual deviates far below the mean
    // (keeps a portfolio of usable residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight time pressure: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: quadratic waste penalty (dead space grows super-linearly in cost)
    let mut score = pr_norm * pr_norm * cap;

    // Stream-progress coupling: early on, allow slack (bins may fill later);
    // late in the stream, punish residual space much harder.
    let urgency = progress * progress;
    score += urgency * pr_norm * cap * 0.8;

    // Smooth interaction: residual vs mean residual across open bins.
    // Placing into a bin whose residual deviates favorably from the mean
    // (i.e., we consume an outlier gap) is rewarded.
    let mean_norm = mean_residual / cap;
    let deviation = pr_norm - mean_norm;
    score -= deviation * deviation * cap * 0.3;
    score -= deviation * cap * 0.15;

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    // (smooth sigmoid-like gate instead of hard threshold).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fit = (pr - nxt) / cap;
        let gate = 1.0 / (1.0 + (-fit * 12.0).exp());
        score -= gate * cap * 0.6;
        // Extra reward if next item would fill bin almost exactly
        let tight = 1.0 - ((pr - nxt) / cap).abs();
        score -= gate * tight * cap * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (penalize alternatives implicitly).
    if fitting_bins_count == 1 {
        score -= cap * 0.9;
    } else {
        // Mild reward when many bins compete: pick the tightest via base term already.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: empty bin has pr == cap. Penalize opening a new bin
    // unless existing fits are terrible; smooth ramp based on open bins count.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let congestion = 1.0 / (1.0 + (-(open_bins_count as f64 - 3.0) / 2.0).exp());
        score += cap * (1.2 - 0.5 * congestion) + urgency * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual < 10 (tiny dead space) -> strong reward.
    // Class 2: post_residual < 25 -> mild reward.
    // Otherwise: penalize large leftovers, especially those below the smallest item (1..=10 unusable-ish).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 35.0;
    } else if post_residual < 25 {
        score -= 10.0;
    } else {
        // large leftover: penalize proportionally to wasted fraction
        score += 0.15 * (post_residual as f64 - 25.0);
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            // reward only if the chain leaves small residue again
            if nr < 10 { score -= 20.0; }
            else if nr < 25 { score -= 6.0; }
            else { score += 0.1 * (nr as f64 - 25.0); }
        } else {
            // next item cannot use this bin's residue: residue is likely dead
            score += 8.0;
        }
    }

    // Integer-division threshold on post_residual relative to quarter-capacity classes.
    let quarter = (bin_capacity / 4) as f64;
    let class = (post_residual as f64 / quarter).floor();
    score += class * 2.5; // deeper-empty classes get mild penalty unless rewarded above

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has neutral waste but incurs an opening cost.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.05 * open_bins_count as f64;
    }

    // Stream progression: late in stream, prefer tighter packing (reward small residuals more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    // Tie-break toward bins below mean residual (fill the emptiest fitting bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are effectively wasted capacity.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // dead space penalty
    } else if post_residual <= 25 {
        // small-but-usable gaps are risky too; penalize softly
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Reward tight fits relative to the bin's current fill.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // barely fits anywhere else (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 70 && fitting_bins_count <= 1 {
            score -= 45.0; // big item with no good home: open a fresh bin
        }
    }

    // Lookahead coupling: if the next item would fit in the resulting
    // residual, reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Early in the stream, be a bit more willing to open bins (build a
    // diverse pool); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        // Perfect 2-step match: strong reward proportional to item size.
        if diff == 0 {
            score -= 40.0 + item_size as f64;
        } else if (next_item_size as u32) <= post_residual {
            // Next item fits: mild reward scaled by how snug the fit is.
            score -= 12.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit into the residual: penalize dead space creation.
            score += 8.0 + diff as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        // But opening a new bin is attractive if no open bin fits well (all residuals small).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving a residual near the mean keeps the fleet balanced and usable.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer tight fits: penalize large post residual relative to capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin (lower post_residual ratio = better fit)
    let fill_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fill_ratio * fill_ratio;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: penalize if post_residual can't serve the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // post_residual can host the next item: reward proportional to leftover after that
            let second_left = post_residual - next_item_size;
            score -= 8.0 + 0.1 * second_left as f64;
        } else {
            // dead space relative to the next item
            score += 10.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just fill as much as possible
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global pressure: many open bins with small residuals -> consolidate
    let global_mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.3 * global_mean_gap;

    // Penalize opening new bins as the stream matures, unless it's a great fit
    if bin_residual == bin_capacity {
        // New-bin candidate
        let openness = 1.0 - progress;
        score += 15.0 + 30.0 * progress;
        // allow new bins early in the stream when item is large
        score -= openness * (item_size as f64 / 100.0) * 20.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Favor reusing existing bins slightly
        score -= 5.0;
    }

    // Mild penalty for very small post_residual that is still nonzero (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor tight fills later); later, dead space is costly.
    let waste_penalty = norm_post * norm_post * (1.0 + 3.0 * progress * progress);
    score += 20.0 * waste_penalty;

    // Reward near-perfect fits with a smooth quadratic reward term.
    let tightness = (norm_post - 0.05).powi(2);
    score -= 30.0 * (-40.0 * tightness).exp();

    // Lookahead coupling: penalize leaving residual that neither helps nor hurts next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.3 * gap * (1.0 - progress);
        // Reward exact lookahead match smoothly.
        score -= 15.0 * (-(gap * gap) / 50.0).exp();
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln() * norm_post * 5.0;

    // Mean-residual deviation: prefer bins whose post-residual tracks the fleet mean,
    // keeping residual distribution balanced (smooth cubic interaction).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + fit_ratio);

    // New-bin candidate: make empty bins mildly attractive only for large items or late stream.
    if bin_residual == bin_capacity {
        score += 10.0 - 12.0 * fit_ratio - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 (capacity quantum)
    let post_mod = post_residual % 10;
    // Residues that are "dead" (small, hard to fill: 1..9) get penalized,
    // residue 0 (perfect fit) heavily rewarded.
    if post_mod == 0 {
        score -= 45.0;
    } else if post_mod <= 3 {
        score += 12.0 + 4.0 * (3 - post_mod) as f64;
    } else if post_mod <= 6 {
        score += 5.0;
    }

    // Integer-division thresholds: large post_residual chunks are good
    if post_residual >= 50 { score -= 20.0; }
    else if post_residual >= 30 { score -= 8.0; }
    else if post_residual >= 20 { score -= 2.0; }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect lookahead fit
        } else if next_item_size < post_residual {
            // reward if next fits, especially into harmonic class of post_residual
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 25.0; } else { score -= 8.0; }
        } else {
            // next item won't fit here: penalize wasting space
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when existing residuals are fragmented (low mean residual)
        score += 35.0 * pressure - 15.0;
        if fitting_bins_count == 0 { score -= 50.0; }
    }

    // Prefer tighter fits overall: relative waste fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    // Early in stream, be slightly conservative (keep bins open for big items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min item size 1, but practically < ~10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < 25 {
        score += 12.0; // risky small gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Coupling with mean residual: placing into a bin below the mean residual
    // evens out residuals, avoiding many half-empty bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot go here; slight penalty for leaving a blocking gap
        score += 3.0;
    }

    // New-bin candidate: opening a new bin wastes (capacity - item) potential;
    // make it attractive only when no good fit exists (large post_residual gap
    // in all bins). Base new-bin score is its own residual minus item.
    if bin_residual == bin_capacity {
        // neutral base = post_residual (= capacity - item), plus a moderate
        // opening cost that fitting-bin rewards above can overcome.
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if post_residual as u32 >= next_item_size {
            // Post residual can host next item: reward closeness of the match.
            score -= 120.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space below next item: penalize proportionally to wasted space.
            let waste = nxt - post_residual as f64;
            score += 3.0 * waste;
        }

        // Bonus when next item also fits tightly relative to mean residual.
        if post_residual as f64 >= nxt && (post_residual as f64 - nxt) <= mean_residual * 0.5 {
            score -= 40.0;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score -= 60.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins give a decent fit.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && next_item_size <= item_size {
            // New bin makes sense if the current item is small relative to lookahead.
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual is above mean (keep flexible bins alive).
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Late-stream tightening: prefer filling bins tightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: squared residual penalizes wasteful gaps.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder anyway: slight penalty
        // unless post_residual is small (already a good squeeze).
        if post_residual > 25 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only allow
    // it when no open bin gives a decent fit (post_residual large relative
    // to item size) or bins are crowded.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin.
        score += 120.0;
        // Early in the stream, opening bins is fine (build a portfolio).
        score -= 60.0 * (1.0 - progress);
        // If many bins are open, prefer reusing one of them.
        score += 5.0 * (open_bins_count as f64).sqrt();
        // Very large items leave little waste in a fresh bin; encourage.
        score -= 50.0 * tightness;
        // If the current bin would leave a huge unusable gap, allow new bin.
        if post_residual > 0 && post_residual < 10 {
            score -= 100.0;
        }
    } else {
        // Reuse reward: filling existing bins is generally good.
        score -= 20.0;
        // Reward bins whose residual deviates favorably from the mean
        // (consume bins with above-average leftover space).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.15 * dev;
        // Tight packing: the closer item fills the bin, the better.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 60.0 * fill_ratio;
        // Penalize leaving dead space that no plausible item (>=1) can use well:
        // small remainders (< typical min item) are effectively dead.
        if post_residual < 5 {
            score -= 25.0;
        }
        // Late in stream: consolidate aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mild exploration noise-free deterministic tie-breaker using state.
    score -= 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: post-residual, with non-linear penalty for awkward dead space.
    // Squared/cubic terms punish large unusable residuals more strongly.
    let mut score = pr
        + 0.35 * pr * pr / cap
        + 0.15 * pr * pr * pr / (cap * cap);

    // Smooth coupling: residual waste weighted by stream progress —
    // later in the stream, tight packing matters more.
    score += 1.5 * progress * (pr / cap) * (pr / cap) * cap;

    // Reward high fill ratio smoothly (cubic in fit).
    score -= 8.0 * fit * fit * fit * cap;

    // Lookahead coupling: bonus if the post-residual smoothly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap);
        score -= 6.0 * match_term * match_term * match_term;
    }

    // Last-chance bin: smooth reward when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual deviates
    // smoothly from the average (consolidation pressure).
    score += 0.5 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in low fractions (small leftovers)
    // are "sealed" bins -> reward them; large leftovers are wasteful.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes of C/8)
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8
    let class_bonus: f64 = match class {
        0 => -14.0,               // perfect/near-perfect seal
        1 => -9.0,                // tiny dead space, excellent
        2 => -5.0,
        3 => -1.0,
        4 => 2.0,                 // half-full: mediocre, keep for flexibility
        5 => 4.0,
        6 => 6.0,
        7 => 8.0,
        _ => 10.0,                // almost untouched bin, wasteful placement
    };
    score += class_bonus;

    // Fine-grained modulo term: reward post residuals that are "harmonic"
    // with common small item sizes (multiples of 10) so future items tile in.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / cap;
            // reward proportional tightness of the follow-up fit
            score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
            // harmonic class of the chain leftover
            let chain_left = post_residual - next_item_size;
            if chain_left <= bin_capacity / 8 {
                score -= 4.0;
            }
            let _ = nxt_frac;
        } else {
            // next item cannot follow here: penalize slightly more if this bin
            // would be the only option (last chance), since sealing it badly hurts.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // placement would leave an awkward (mid-fraction) residual or no bin fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to how many bins are open
        // and how far along the stream we are (late in stream, reuse more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 6.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) + 4.0 * progress;
        // If the item would leave a very small residual in an existing bin, that
        // existing bin is great; make new bin unattractive.
        if pr <= cap * 0.125 {
            new_bin_cost += 10.0;
        }
        // If next item is large and current bins are crowded, new bin more tolerable.
        if next_item_size >= (bin_capacity as u32) * 3 / 4 {
            new_bin_cost -= 3.0;
        }
        score += new_bin_cost;
    }

    // Mild global pressure: when mean residual is high, encourage consolidating
    // into existing bins (punish placements that keep residual high).
    score += 0.05 * (pr - mean_residual);

    // Slight preference for tighter fits overall (nonlinear in fraction).
    score += 8.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize very small gaps that likely become dead space under unknown distribution.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 2.0;
    // New-bin candidate gets extra penalty when many bins are open.
    if bin_residual == bin_capacity {
        score += 60.0 + pressure;
    }

    // Lookahead: if next item fits in the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // If next item cannot fit in the gap and gap is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins tighter than the mean residual (better-packed bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight packing (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: perfect match for the next item is extremely desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // If the next item fits into the post-residual, reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize small unusable leftovers.
        score += 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // this item leaves a large, useful residual and few bins fit it.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        if fitting_bins_count <= 2 {
            score -= 120.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can still fit in the post-residual, reward leaving that space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space too small for the next item: penalize proportionally.
            score += 0.25 * post_residual as f64 * (1.0 - fit_ratio);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin, unless the item is large relative to capacity
    // or the stream is early and we have room to grow a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 18.0 - 20.0 * size_ratio - 10.0 * (1.0 - progress) - 2.0 * open_pressure.min(3.0);
        // A new bin is attractive if no open bin fits well (post_residual here equals capacity - item).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Mild penalty for wasting a bin whose residual is much larger than needed.
        let waste = bin_residual as f64 - item_size as f64;
        score += 0.05 * waste * waste / bin_capacity as f64;
    }

    // Global state coupling: when mean residual is low, conserve open-bin space more aggressively.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f32, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
