    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: coarse dead-space classes via integer division.
    // Residuals in (0..10] are "harmonic sweet spots" (likely fillable by small items 1..10).
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 25.0,               // tiny residual: excellent
        1 => score -= 12.0,               // 11..20: good
        2 => score -= 5.0,                // 21..30: acceptable
        3 | 4 => score += 3.0,            // 31..50: mediocre zone
        5 | 6 => score += 8.0,            // 51..70: awkward dead space
        _ => score += 14.0,               // 71+: very wasteful placement
    }

    // Exact harmonic alignment: residual divisible into clean fractions of capacity.
    if post_residual > 0 && (bin_capacity % post_residual == 0) {
        score -= 10.0;
    }
    // Half/quarter capacity harmonics are common item sizes.
    if post_residual == bin_capacity / 2 || post_residual == bin_capacity / 4 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Exact match is a perfect harmonic continuation.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; mildly penalize leaving mid-range gaps.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be left
    // with a very awkward residual. Baseline penalty decays as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkwardness = (mean_residual - post_residual as f64).max(0.0);
        score += 30.0 - 10.0 * progress - awkwardness.min(25.0);
    }

    // Prefer tighter bins overall: closeness of fit bonus.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Mild entropy: spread across many open bins is discouraged slightly.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range
    // means residual < 1 is impossible, but tiny residuals < 10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Penalize residual that cannot fit the lookahead item but could otherwise be useful
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Tight fit reward relative to item size
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless it enables a near-perfect pack
    if bin_residual == bin_capacity {
        let waste = 100.0 - item_size as f64;
        score += 55.0 - 0.4 * waste;
        if item_size >= 90 { score -= 60.0; } // big items deserve fresh bins
    }

    // Progress: tighten standards late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly matches the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits here: reward proportionally to how tight the pair is.
            score -= 120.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize leaving dead space.
            score += 0.5 * (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Tightness reward: smaller post residual relative to capacity is better.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: penalize bins far below mean (wasting a tight bin),
    // mildly favor bins with residual close to mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // New-bin candidate: neutral-ish baseline, only attractive when the item is large
    // (poor fit anywhere) or when current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64; // high => bins nearly full
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 40.0 * pressure - 30.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            // A fresh bin can also host the next big item: slight bonus.
            score -= 10.0;
        }
        if post_residual == 0 {
            score -= 1000.0; // exact fill of a fresh bin
        }
    }

    score
}
